<?php
declare(strict_types=1);
$version=$argv[1]??'';if(!in_array($version,['original','fase1'],true)){exit(2);} $root=dirname(__DIR__);require $root.'/librerias/'.$version.'/simple_html_dom.php';
function value_repr(mixed $v):mixed{if(is_array($v))return array_map('value_repr',$v);if(is_object($v))return ['object'=>get_class($v)];if(is_resource($v))return ['resource'=>get_resource_type($v)];return $v;}
$functions=[];foreach(['file_get_html','str_get_html','dump_html_tree'] as $fn){$r=new ReflectionFunction($fn);$functions[$fn]=['parameters'=>array_map(fn($p)=>['name'=>$p->getName(),'optional'=>$p->isOptional(),'default'=>$p->isDefaultValueAvailable()?value_repr($p->getDefaultValue()):null,'variadic'=>$p->isVariadic()],$r->getParameters()),'returns'=>(string)$r->getReturnType()];}
$classes=[];foreach(['simple_html_dom','simple_html_dom_node'] as $cn){$r=new ReflectionClass($cn);$methods=[];foreach($r->getMethods(ReflectionMethod::IS_PUBLIC) as $m){if($m->getDeclaringClass()->getName()!==$cn)continue;$methods[$m->getName()]=['static'=>$m->isStatic(),'parameters'=>array_map(fn($p)=>['name'=>$p->getName(),'optional'=>$p->isOptional(),'default'=>$p->isDefaultValueAvailable()?value_repr($p->getDefaultValue()):null,'variadic'=>$p->isVariadic()],$m->getParameters()),'returns'=>(string)$m->getReturnType()];}ksort($methods);$properties=[];foreach($r->getProperties(ReflectionProperty::IS_PUBLIC) as $p){$properties[$p->getName()]=['static'=>$p->isStatic()];}ksort($properties);$classes[$cn]=['methods'=>$methods,'properties'=>$properties];}
$constants=[];foreach(get_defined_constants(true)['user']??[] as $k=>$v){if(str_starts_with($k,'HDOM_')||in_array($k,['DEFAULT_TARGET_CHARSET','DEFAULT_BR_TEXT','DEFAULT_SPAN_TEXT','MAX_FILE_SIZE'],true))$constants[$k]=$v;}ksort($constants);
$out=['version'=>$version,'functions'=>$functions,'classes'=>$classes,'constants'=>$constants];file_put_contents($root.'/resultados/'.$version.'/api_publica.json',json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
